class OffersTable extends React.PureComponent {
    render() {
        const { offers, onRowClick, onOfferNoClick, getStatusColor, updatedOfferNos = [] } = this.props;
        const filtered = offers.filter(o => o.status !== "Order Received" && o.status !== "Order Lost");
        const offersUpdated = filtered.filter(o => updatedOfferNos.includes(o.offer_no)).length;
        return (
            <>
                <Grid item xs={12}>
                    <Divider><Typography variant="caption" color="text.secondary" sx={{ px: 1 }}>Offers{filtered.length ? ` (${offersUpdated}/${filtered.length} updated)` : ''}</Typography></Divider>
                </Grid>
                <Grid item xs={12}>
                    <TableContainer component={Paper} variant="outlined" sx={{ overflowX: 'auto', borderRadius: 1 }}>
                        <Table size="small">
                            <TableHead>
                                <TableRow sx={{ bgcolor: 'primary.main' }}>
                                    <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold', whiteSpace: 'nowrap', py: 1.5 }}>Offer No.</TableCell>
                                    <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold', whiteSpace: 'nowrap', py: 1.5 }}>Offer Date</TableCell>
                                    <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold', whiteSpace: 'nowrap', py: 1.5 }}>Offer Value</TableCell>
                                    <TableCell sx={{ color: 'primary.contrastText', fontWeight: 'bold', whiteSpace: 'nowrap', py: 1.5 }}>Status</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {filtered.length === 0 ? (
                                    <TableRow><TableCell colSpan={4} sx={{ textAlign: 'center', py: 3, color: 'text.secondary' }}>No offers found</TableCell></TableRow>
                                ) : filtered.map((offer) => (
                                    <TableRow key={offer.id} hover sx={{ cursor: 'pointer', '&:last-child td': { borderBottom: 0 } }} onClick={() => onRowClick(offer)}>
                                        <TableCell sx={{ whiteSpace: 'nowrap', fontWeight: 600, py: 1.5, color: 'primary.main', cursor: 'pointer', textDecoration: 'underline', textDecorationStyle: 'dotted' }} onClick={(e) => onOfferNoClick(e, offer)}>
                                            {offer.offer_no}
                                        </TableCell>
                                        <TableCell sx={{ whiteSpace: 'nowrap', py: 1.5 }}>{offer.offer_date}</TableCell>
                                        <TableCell sx={{ whiteSpace: 'nowrap', py: 1.5 }}>{offer.offer_value}</TableCell>
                                        <TableCell sx={{ py: 1.5 }}>
                                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                                <Chip label={offer.status} color={getStatusColor(offer.status)} size="small" sx={{ fontSize: '0.72rem', height: 'auto', py: 0.4, whiteSpace: 'nowrap' }} />
                                                {updatedOfferNos.includes(offer.offer_no) && <CheckCircleIcon sx={{ color: 'success.main', fontSize: 20 }} titleAccess="Updated" />}
                                            </Box>
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                </Grid>
            </>
        );
    }
}

