    CalculateTotalClaim=async()=>{
        // console.log("🚀 ~ file: salesvisit.js:338 ~ salesvisit ~ CalculateTotalClaim=async ~ TravelType:", this.state.TravelType)
        let TotalClaim = parseFloat(this.state.LocalFare)>0?parseFloat(this.state.LocalFare):0;
        if(this.state.TravelType===4){
            // let RateInfo = this.state.MasterData.rate.find((data)=>data.user_type_id===this.state.user_type_id)
            let RateInfo = this.state.MasterData.rate.find((data)=>data.user_type_id===(this.state.vehicle_type==="two wheeler"?4:5))
            // console.log("🚀 ~ file: salesvisit.js:340 ~ salesvisit ~ CalculateTotalClaim=async ~ RateInfo:", RateInfo)
            let Rate = RateInfo===undefined?0:RateInfo.rate
            // console.log("🚀 ~ file: salesvisit.js:342 ~ salesvisit ~ CalculateTotalClaim=async ~ Rate:", Rate)
            TotalClaim = this.state.LocalFare*Rate;
            if(this.state.VisitType === "Outstation"){
                // this.state.AirBusTrain,this.state.AutoBusTaxi,this.state.BoardingExpense,this.state.LoadgingExpense
                TotalClaim += this.state.AirBusTrain===""?0:(parseFloat(this.state.AirBusTrain)>0?parseFloat(this.state.AirBusTrain):0);
                TotalClaim += this.state.AutoBusTaxi===""?0:(parseFloat(this.state.AutoBusTaxi)>0?parseFloat(this.state.AutoBusTaxi):0);
                TotalClaim += this.state.BoardingExpense===""?0:(parseFloat(this.state.BoardingExpense)>0?parseFloat(this.state.BoardingExpense):0);
                TotalClaim += this.state.LoadgingExpense===""?0:(parseFloat(this.state.LoadgingExpense)>0?parseFloat(this.state.LoadgingExpense):0);
            }
            TotalClaim += parseFloat(this.state.toll_charges);
            await this.setState({
                total_claim: TotalClaim.toFixed(2),
                fare: this.state.LocalFare*Rate
            })
            // console.log("🚀 ~ file: salesvisit.js:346 ~ salesvisit ~ CalculateTotalClaim=async ~ this.state.LocalFare*Rate:", this.state.LocalFare*Rate)
        }else{
            if(this.state.VisitType === "Outstation"){
                // this.state.AirBusTrain,this.state.AutoBusTaxi,this.state.BoardingExpense,this.state.LoadgingExpense
                TotalClaim += this.state.AirBusTrain===""?0:(parseFloat(this.state.AirBusTrain)>0?parseFloat(this.state.AirBusTrain):0);
                TotalClaim += this.state.AutoBusTaxi===""?0:(parseFloat(this.state.AutoBusTaxi)>0?parseFloat(this.state.AutoBusTaxi):0);
                TotalClaim += this.state.BoardingExpense===""?0:(parseFloat(this.state.BoardingExpense)>0?parseFloat(this.state.BoardingExpense):0);
                TotalClaim += this.state.LoadgingExpense===""?0:(parseFloat(this.state.LoadgingExpense)>0?parseFloat(this.state.LoadgingExpense):0);
            }
            TotalClaim += parseFloat(this.state.toll_charges);
            await this.setState({
                total_claim: TotalClaim.toFixed(2)
            })
        }
        // console.log("🚀 ~ file: salesvisit.js:351 ~ salesvisit ~ CalculateTotalClaim=async ~ total_claim:", this.state.total_claim)
    }
