    ToBase64 = file => new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result);
        reader.onerror = error => reject(error);
    })
    FilesChanges = async () => {
        var allowedExtensions =  /(\.pdf|\.jpg|\.png|\.jpeg)$/i;
        let UploadedFiles = document.getElementById("selectedFiles");
        let files = UploadedFiles.files;
        if (files.length > 0) {
            var filePath = UploadedFiles.value;
            if (!allowedExtensions.exec(filePath)) {
                await this.SnackbarActions({key:"Open",variant:"warning",Message:'INVLIAD FILE FORMAT...! Note:- Allowed Only PDF,jpg,png',TimeOut:10000})
                UploadedFiles.value = '';
                return false;
            }else{
                let TempImagesBase64Data = [];
                for (let i = 0; i <files.length; i++) {
                    TempImagesBase64Data.push(await this.ToBase64(files[i]));
                }
                await this.setState({TempImagesBase64Data: TempImagesBase64Data})
            }
        }
    }
