    SaveOfferUpdate = async () => {
        const isOrderLost = this.state.OfferDialogStatus === "Order Lost";
        if (isOrderLost) {
            if (!this.state.OfferOLToWhom) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Order Lost to Whom", TimeOut: 4000 }); return;
            }
            if (this.state.OfferOLToWhom === "Others" && !this.state.OfferOLToName.trim()) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter Order Lost to Name", TimeOut: 4000 }); return;
            }
            if (!this.state.OfferOLPrice) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter Price at which Order Lost", TimeOut: 4000 }); return;
            }
            if (!this.state.OfferOLDelivery.trim()) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter Delivery terms", TimeOut: 4000 }); return;
            }
            if (!this.state.OfferOLPaymentTerms.trim()) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter Payment Terms", TimeOut: 4000 }); return;
            }
            if (!this.state.OfferOLAgainst) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Order Lost Against Details", TimeOut: 4000 }); return;
            }
            if (["Supply Price","Installation Price","Supply & Installation Price"].includes(this.state.OfferOLAgainst) && !this.state.OfferOLPriceDetails) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Price Details (%)", TimeOut: 4000 }); return;
            }
            if (!this.state.OfferOLConsultant.trim()) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter Consultant Name", TimeOut: 4000 }); return;
            }
            if (!this.state.OfferOLReason.trim()) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter Reason", TimeOut: 4000 }); return;
            }
            if (!this.state.OfferOLSpecifyDetail.trim()) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please specify in detail", TimeOut: 4000 }); return;
            }
            if (!this.state.OfferOLOption) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select an Option", TimeOut: 4000 }); return;
            }
            await this.setState({ OfferSaving: true });
            var Data = {
                urlapi: "salesvisit_stage/saveOrderLostDetails",
                method: "POST",
                data: {
                    offer_no:       this.state.SelectedOffer.offer_no,
                    userid:         this.state.userId,
                    order_lost_to_whom: this.state.OfferOLToWhom,
                    order_lost_to_name: this.state.OfferOLToName,
                    price:          this.state.OfferOLPrice,
                    against:        this.state.OfferOLAgainst,
                    price_details:  this.state.OfferOLPriceDetails,
                    delivery:       this.state.OfferOLDelivery,
                    payment_terms:  this.state.OfferOLPaymentTerms,
                    consultant_name:this.state.OfferOLConsultant,
                    reason:         this.state.OfferOLReason,
                    specify_detail: this.state.OfferOLSpecifyDetail,
                    option:         this.state.OfferOLOption,
                }
            };
            var resp = await ProcessRequest(Data);
            if (resp !== null && resp.respCode === 1 && resp.respText === "success") {
                let updatedOffers = this.state.ClientOffers.map(o =>
                    o.id === this.state.SelectedOffer.id ? { ...o, status: "Order Lost" } : o
                );
                await this.setState({ ClientOffers: updatedOffers, OfferSaving: false, OfferDebtorChanged: true });
                await this.SnackbarActions({ key: "Open", variant: "success", Message: "Order Lost details saved successfully", TimeOut: 3000 });
                this.CloseOfferDialog();
            } else {
                await this.setState({ OfferSaving: false });
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: resp !== null ? resp.respText : "Server Not Responding....!", TimeOut: 4000 });
            }
        } else {
            // All offer-update details must be filled before this row can be saved (so an
            // incomplete offer can never be part of the submit).
            if (this.state.OfferDialogStatus === "") {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Offer Status", TimeOut: 4000 }); return;
            }
            if (this.state.OfferDialogNextAction === "") {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Next Action", TimeOut: 4000 }); return;
            }
            if (this.state.OfferDialogNextAction === "Others" && !this.state.OfferDialogNextActionOther.trim()) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please specify Next Action", TimeOut: 4000 }); return;
            }
            if (this.state.OfferDialogDiscussionType === "") {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Discussion Type", TimeOut: 4000 }); return;
            }
            if (!this.state.OfferDialogRemarks.trim()) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please enter Remarks", TimeOut: 4000 }); return;
            }
            if (!this.state.OfferDialogReminderDate) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Reminder Date", TimeOut: 4000 }); return;
            }
            if (!this.state.OfferDialogDate) {
                await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Offer Expected Date", TimeOut: 4000 }); return;
            }
            await this.setState({ OfferSaving: true });
            const newUpdate = {
                offer_no:          this.state.SelectedOffer.offer_no,
                offer_status:      this.state.OfferDialogStatus,
                next_action:       this.state.OfferDialogNextAction,
                next_action_other: this.state.OfferDialogNextActionOther,
                next_action_reason: this.state.OfferDialogNextAction === "Others" ? this.state.OfferDialogNextActionReason : "",
                discussion_type:   this.state.OfferDialogDiscussionType,
                remarks:           this.state.OfferDialogRemarks,
                reminder_date:     this.state.OfferDialogReminderDate,
                expected_date:     this.state.OfferDialogDate,
                order_received:    this.state.OfferDialogOrderReceived,
            };
            const existingUpdates = this.state.LastOfferUpdates.filter(u => u.offer_no !== newUpdate.offer_no);
            await this.setState({ LastOfferUpdates: [...existingUpdates, newUpdate] });
            let updatedOffers = this.state.ClientOffers.map(o =>
                o.id === this.state.SelectedOffer.id ? { ...o, status: this.state.OfferDialogStatus } : o
            );
            await this.setState({ ClientOffers: updatedOffers, OfferSaving: false });
            await this.SnackbarActions({ key: "Open", variant: "success", Message: "Offer updated successfully", TimeOut: 3000 });
            this.CloseOfferDialog();
        }
    }
