    mapDebtorDetails = (debitordetails) => {
        if (!Array.isArray(debitordetails)) return [];
        const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
        const formatDate = (dateStr) => {
            if (!dateStr) return '';
            const d = new Date(dateStr);
            return `${String(d.getDate()).padStart(2, '0')}-${months[d.getMonth()]}-${d.getFullYear()}`;
        };
        return debitordetails.map((item, idx) => ({
            id:             idx + 1,
            invoice_no:     item.invoiceno    || '',
            invoice_date:   formatDate(item.invoicedate),
            workorder_no:   String(item.checklistid || ''),
            invoice_amount: item.InvoiceAmount !== undefined && item.InvoiceAmount !== null
                            ? item.InvoiceAmount.toLocaleString('en-IN')
                            : '',
            project_name:   item.ProjectName  || '',
            expected_date:  formatDate(item.paymentduedate),
            overdue_days:   item.overdue_days  ?? 0,
        }));
    }
    mapOfferDetails = (offerdetails) => {
        if (!Array.isArray(offerdetails)) return [];
        const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
        return offerdetails.map((item, idx) => {
            let offer_date = '';
            if (item.OfferDate) {
                const d = new Date(item.OfferDate);
                offer_date = `${String(d.getDate()).padStart(2, '0')}-${months[d.getMonth()]}-${d.getFullYear()}`;
            }
            return {
                id: idx + 1,
                offer_no:    item.OfferNO    || '',
                offer_date,
                description: item.ProjectName || '',
                offer_value: item.OfferTotal !== undefined && item.OfferTotal !== null
                    ? item.OfferTotal.toLocaleString('en-IN')
                    : '',
                status:      item.OrderStatus || '',
            };
        });
    }
