    CloseDebtorDialog = () => {
        this.setState({
            DebtorDialogOpen: false,
            SelectedDebtor: null,
            DebtorDialogNextAction: "",
            DebtorDialogNextActionOther: "",
            DebtorDialogNextActionReason: "",
            DebtorDialogReminderDate: null,
            DebtorDialogExpectedDate: null,
            DebtorDialogReasonForDelay: "",
        });
    }
    SaveDebtorUpdate = async () => {
        // All debtor-update details must be filled before this row can be saved.
        if (this.state.DebtorDialogNextAction === "") {
            await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Next Action", TimeOut: 4000 }); return;
        }
        if (this.state.DebtorDialogNextAction === "Others" && !this.state.DebtorDialogNextActionOther.trim()) {
            await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please specify Next Action", TimeOut: 4000 }); return;
        }
        if (!this.state.DebtorDialogReminderDate) {
            await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Reminder Date", TimeOut: 4000 }); return;
        }
        if (!this.state.DebtorDialogExpectedDate) {
            await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Expected Date", TimeOut: 4000 }); return;
        }
        if (this.state.DebtorDialogReasonForDelay === "") {
            await this.SnackbarActions({ key: "Open", variant: "warning", Message: "Please select Reason for Delay", TimeOut: 4000 }); return;
        }
        await this.setState({ DebtorSaving: true });
        const newUpdate = {
            invoice_no:        this.state.SelectedDebtor.invoice_no,
            next_action:       this.state.DebtorDialogNextAction,
            next_action_other: this.state.DebtorDialogNextActionOther,
            next_action_reason: this.state.DebtorDialogNextAction === "Others" ? this.state.DebtorDialogNextActionReason : "",
            reminder_date:     this.state.DebtorDialogReminderDate,
            expected_date:     this.state.DebtorDialogExpectedDate,
            reason_for_delay:  this.state.DebtorDialogReasonForDelay,
        };
        const existingUpdates = this.state.LastDebtorUpdates.filter(u => u.invoice_no !== newUpdate.invoice_no);
        await this.setState({ LastDebtorUpdates: [...existingUpdates, newUpdate], DebtorSaving: false, OfferDebtorChanged: true });
        await this.SnackbarActions({ key: "Open", variant: "success", Message: "Debtor details updated successfully", TimeOut: 3000 });
        this.CloseDebtorDialog();
    }
