import React from 'react';
import { Dialog, DialogTitle, DialogContent, DialogContentText, DialogActions, Button } from '@mui/material';

// Reusable confirmation dialog.
// Drive it from a small piece of state and an onConfirm callback:
//   <ConfirmDialog open={...} title="..." message="..." confirmLabel="Remove" danger
//                  onConfirm={...} onCancel={...} />
export default function ConfirmDialog({
  open,
  title,
  message,
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  danger = false,
  busy = false,
  onConfirm,
  onCancel,
}) {
  return (
    <Dialog
      open={!!open}
      onClose={busy ? undefined : onCancel}
      maxWidth="xs"
      fullWidth
      PaperProps={{ sx: { mx: { xs: 2, sm: 3 }, borderRadius: 2 } }}
    >
      {title ? <DialogTitle sx={{ fontWeight: 700, pb: 1 }}>{title}</DialogTitle> : null}
      <DialogContent>
        <DialogContentText sx={{ color: '#444', fontSize: 14, lineHeight: 1.5 }}>{message}</DialogContentText>
      </DialogContent>
      <DialogActions sx={{ p: 2, gap: 1 }}>
        <Button onClick={onCancel} variant="outlined" fullWidth disabled={busy} sx={{ textTransform: 'none' }}>
          {cancelLabel}
        </Button>
        <Button
          onClick={onConfirm}
          variant="contained"
          fullWidth
          autoFocus
          disabled={busy}
          color={danger ? 'error' : 'primary'}
          sx={{ textTransform: 'none', ...(danger ? {} : { bgcolor: '#534AB7', '&:hover': { bgcolor: '#3d35a0' } }) }}
        >
          {confirmLabel}
        </Button>
      </DialogActions>
    </Dialog>
  );
}
